Prob060_m2014_q4k.code:
module TopModule (
    input  clk,
    input  resetn,
    input  in,
    output out
);

    // Internal signals for the shift register stages
    reg [3:0] shift_reg;

    // Synchronous reset and shift operation on positive edge of clock
    always @(posedge clk) begin
        if (!resetn) begin
            // Active-low synchronous reset: set all flops to 0
            shift_reg <= 4'b0000;
        end else begin
            // Shift right: new input goes to MSB (bit 3), LSB (bit 0) is shifted out
            shift_reg <= {in, shift_reg[3:1]};
        end
    end

    // Output assignment: connect the LSB of the shift register to the output port
    assign out = shift_reg[0];

endmodule

