    // Synchronous reset and enable logic
    always @(posedge clk) begin
        if (reset)
            count <= 4'b0000;
        else if (slowena) begin
            // Count from 0 to 9, then wrap around to 0
            if (count == 4'd9)
                count <= 4'b0000;
