module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 2 bits
    // 2'b00: State A (reset/initial)
    // 2'b01: State B (f=1 pulse)
    // 2'b10: State C (monitoring x for 1,0,1)
    // 2'b11: State D (g=1 active, monitoring y)
    reg [1:0] state, next_state;

    // Outputs: f is 1 only in State B; g is 1 in State D
    assign f = (state == 2'b01);
    assign g = (state == 2'b11);

    // State register (positive edge, synchronous active-low reset)
    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            state <= 2'b00;
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            2'b00: begin // State A
                if (!resetn)
                    next_state <= 2'b00;
                else
                    next_state <= 2'b01; // After de-assertion, go to State B
            end
            2'b01: begin // State B (f=1 for one cycle)
                next_state <= 2'b10; // Transition to monitor x
            end
            2'b10: begin // State C (monitor x for 1,0,1)
                // Sequence detector: expecting 1, then 0, then 1
                if (x == 1'b1)
                    next_state <= 2'b11; // First '1' received, go to D
                else if (x == 1'b0)
                    next_state <= 2'b10; // Stay in C, waiting for first 1
                else
                    next_state <= 2'b10;
            end
            2'b11: begin // State D (g=1, monitoring y)
                if (y == 1'b1)
                    next_state <= 2'b11; // y=1 within 2 cycles, maintain g=1
                else if (state[0]) // If previous cycle y was 0 (state[0] tracks cycle count implicitly)
                    next_state <= 2'b00; // y not 1 within 2 cycles, reset to A
                else
                    next_state <= 2'b11; // First cycle y=0, stay in D
            end
            default: next_state <= 2'b00;
        endcase
    end

endmodule

