module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state register
    reg [1:0] state; // 2-bit state encoding

    // State encoding:
    // 2'b00: Below s[0] (all outputs asserted, dfr=1)
    // 2'b01: Between s[1] and s[0] (fr0, fr1; dfr=0)
    // 2'b10: Between s[2] and s[1] (fr0;   dfr=0)
    // 2'b11: Above s[2]  (none;         dfr=0)

    // Combinational logic for outputs based on current state
    assign fr0 = (state != 2'b11); // fr0 is 0 only when above s[2]
    assign fr1 = (state == 2'b01); // fr1 is 1 only when between s[1] and s[0]
    assign fr2 = (state == 2'b00); // fr2 is 1 only when below s[0]
    assign dfr = (state == 2'b00); // dfr is 1 only when below s[0]

    // State register: synchronous reset, otherwise hold state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00; // Reset state: below s[0]
        end else begin
            // Determine next state based on sensor input s
            case (s)
                3'b111: state <= 2'b11; // Above s[2]
                3'b110: state <= 2'b10; // Between s[2] and s[1]
                3'b100: state <= 2'b01; // Between s[1] and s[0] (s[1]=0, s[0]=0 -> actually 3'b100 means s[2]=1,s[1]=0,s[0]=0 -> below s[0]? Wait.)
                // Let's re-evaluate sensor patterns based on specification.
                // s is 3 bits: s[2] highest, s[0] lowest.
                // Assertion means water level is at or above that sensor.
                // "Above s[2]" means s[2] is asserted (and presumably s[1], s[0] also asserted if we consider continuity, but spec says "s[0], s[1], s[2]" asserted).
                // "Between s[2] and s[1]" means s[0], s[1] asserted, s[2] not.
                // "Between s[1] and s[0]" means s[0] asserted, s[1] not.
                // "Below s[0]" means none asserted.

                // Let's map sensor patterns to states.
                // Pattern: s[2] s[1] s[0]
                // 1     1     1   -> Above s[2] -> state 11 (0b11)
                // 0     1     1   -> Between s[2] and s[1] -> state 10 (0b10)
                // 0     0     1   -> Between s[1] and s[0] -> state 01 (0b01)
                // 0     0     0   -> Below s[0] -> state 00 (0b00)

                // Note: The specification table lists "Sensors Asserted".
                // For "Between s[2] and s[1]": s[0], s[1] asserted. This implies s[2] is 0.
                // For "Between s[1] and s[0]": s[0] asserted. This implies s[1] is 0.
                // For "Below s[0]": None asserted. s[0]=0.

                // Therefore, the input vector s directly corresponds to the asserted sensors.
                // We can use case statement on s.

                3'b111: state <= 2'b11; // Above s[2]
                3'b011: state <= 2'b10; // Between s[2] and s[1] (s[1]=1, s[0]=1, s[2]=0)
                3'b001: state <= 2'b01; // Between s[1] and s[0] (s[0]=1, s[1]=0, s[2]=0)
                3'b000: state <= 2'b00; // Below s[0]
                default: state <= state; // Hold
            endcase
        end
    end

endmodule

