module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        S_WALK_LEFT   = 3'b000,
        S_WALK_RIGHT  = 3'b001,
        S_FALLING     = 3'b010,
        S_DIGGING     = 3'b011,
        S_SPLATTERED  = 3'b100
    } state_t;

    // Outputs
    assign walk_left   = (state == S_WALK_LEFT);
    assign walk_right  = (state == S_WALK_RIGHT);
    assign aaah        = (state == S_FALLING);
    assign digging     = (state == S_DIGGING);

    // Registers
    state_t state, next_state;
    logic [4:0] fall_counter;  // counts up to 31, enough for >20
    state_t walk_dir_saved;    // direction saved before falling/digging

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK_LEFT;
            fall_counter <= 0;
            walk_dir_saved <= S_WALK_LEFT;
        end else begin
            state <= next_state;
            // fall_counter updates based on state
            case (state)
                S_FALLING: begin
                    if (fall_counter < 31)
                        fall_counter <= fall_counter + 1;
                end
                default: fall_counter <= fall_counter; // hold
            endcase
        end
    end

    // Next-state logic
    always_comb begin
        // Default next state is current state
        next_state = state;

        case (state)
            S_WALK_LEFT: begin
                // Priority 1: Fall if ground disappears
                if (!ground) begin
                    next_state = S_FALLING;
                    fall_counter <= 0;  // start counting
                    walk_dir_saved <= S_WALK_LEFT;
                end
                // Priority 2: Dig if ground=1 and dig=1
                else if (ground && dig) begin
                    next_state = S_DIGGING;
                    walk_dir_saved <= S_WALK_LEFT;  // save direction before digging
                end
                // Priority 3: Switch direction if bumped
                else begin
                    if (bump_left && !bump_right)
                        next_state = S_WALK_RIGHT;
                    else if (bump_right && !bump_left)
                        next_state = S_WALK_LEFT;  // already walking left, but bump_right while walking left -> walk left (no change? Actually should stay left)
                    else if (bump_left && bump_right)
                        next_state = S_WALK_RIGHT;  // switch directions: left->right
                    // else stay walking left
                end
            end

            S_WALK_RIGHT: begin
                if (!ground) begin
                    next_state = S_FALLING;
                    fall_counter <= 0;
                    walk_dir_saved <= S_WALK_RIGHT;
                end
                else if (ground && dig) begin
                    next_state = S_DIGGING;
                    walk_dir_saved <= S_WALK_RIGHT;
                end
                else begin
                    if (bump_right && !bump_left)
                        next_state = S_WALK_LEFT;
                    else if (bump_left && !bump_right)
                        next_state = S_WALK_RIGHT;  // already walking right
                    else if (bump_left && bump_right)
                        next_state = S_WALK_LEFT;  // switch: right->left
                end
            end

            S_FALLING: begin
                // If ground reappears
                if (ground) begin
                    if (fall_counter > 20) begin
                        // Splatter
                        next_state = S_SPLATTERED;
                    end else begin
                        // Resume walking in saved direction
                        if (walk_dir_saved == S_WALK_LEFT)
                            next_state = S_WALK_LEFT;
                        else
                            next_state = S_WALK_RIGHT;
                    end
                end
                // else stay falling, counter already incremented in register
            end

            S_DIGGING: begin
                // If ground disappears (reaches other side)
                if (!ground) begin
                    next_state = S_FALLING;
                    fall_counter <= 0;
                    walk_dir_saved <= walk_dir_saved;  // keep the saved direction (direction before digging)
                end
                // If ground=1 and dig=1, stay digging
                else if (ground && dig) begin
                    next_state = S_DIGGING;
                end
                // If ground=1 and !dig, stop digging and resume walking in saved direction
                else if (ground && !dig) begin
                    if (walk_dir_saved == S_WALK_LEFT)
                        next_state = S_WALK_LEFT;
                    else
                        next_state = S_WALK_RIGHT;
                end
                // else stay digging (shouldn't happen if ground=1 and dig=1)
            end

            S_SPLATTERED: begin
                // Stay splattered forever (until reset)
                next_state = S_SPLATTERED;
            end
        endcase
    end

endmodule
